// ByState answers for a state as id<<4|meta, which is how this
// version's chunk data packs one.
//
// The encoding is worth naming because the game packs the same fact the other
// way round elsewhere, and a lookup keyed that way resolves every state and
// answers about the wrong block every time.
func (registry *blockMovementRegistry) ByState(state data.BlockStateID) (bool, bool) {
	return registry.ByID(data.BlockID(state >> 4))
}

func (registry *blockMovementRegistry) ByID(id data.BlockID) (bool, bool) {
	blocks, known := registry.byID[id]
	return blocks, known
}

// FallsByState resolves the state to its block and answers for that, because
// in this version falling is a fact about the block.
func (registry *blockMovementRegistry) FallsByState(state data.BlockStateID) (bool, bool) {
	return registry.FallsByID(data.BlockID(state >> 4))
}

func (registry *blockMovementRegistry) FallsByID(id data.BlockID) (bool, bool) {
	falls, known := registry.falls[id]
	return falls, known
}

// ClimbableByState resolves the state to its block, for the same reason
// FallsByState does.
func (registry *blockMovementRegistry) ClimbableByState(state data.BlockStateID) (bool, bool) {
	return registry.ClimbableByID(data.BlockID(state >> 4))
}

func (registry *blockMovementRegistry) ClimbableByID(id data.BlockID) (bool, bool) {
	climbable, known := registry.climbable[id]
	return climbable, known
}

func (registry *blockMovementRegistry) All() data.BlockMovementIndex {
	return registry.byID.Clone()
}
